## atom's OWN constraints; `domain()` (atom.py:545, method(domain, Atom))
## appends the arguments' domains.  Overriding `domain` here dropped them
## (claims audit C0261, 1.9.2.9158).
method(atom_domain, TrInv) <- function(x) {
  list(PSD(.args(x)[[1L]]))
}

