# -- .grad: subgradient of tr(X^-1) -------------------------------
## CVXPY SOURCE: atoms/tr_inv.py:88-108 (tr_inv._grad).
## d/dX tr(X^-1) = -X^{-T} X^{-T} = -(X^{-T})^2.
## NULL if min eigenvalue <= 0 (outside the open PSD cone).
## `tol = 0`: CVXPY's np.linalg.inv has no conditioning test, so an
## ill-conditioned but positive definite X still yields a gradient; base
## solve() would abort "computationally singular" below rcond eps (claims
## audit C0261, 1.9.2.9158; same as .mf_inv in matrix_frac.R).
method(.grad, TrInv) <- function(x, values, ...) {
  X <- as.matrix(values[[1L]])
  ev <- .eigvalsh(X, only_values = TRUE)$values
  if (min(ev) <= 0) return(list(NULL))
  D <- t(solve(X, tol = 0))
  D <- -D %*% D
  rows <- as.integer(prod(.arg_shape(x)))
  list(.dense_to_csc_vector(as.numeric(D), rows))
}

# ==================================================================
# Convenience function
# ==================================================================

#' Trace of matrix inverse
#'
#' Computes \eqn{\mathrm{tr}(X^{-1})} for PSD matrix X.
#'
#' @param X A square PSD matrix expression
#' @returns An expression representing \eqn{\mathrm{tr}(X^{-1})}
#' @export
tr_inv <- function(X) {
  TrInv(X)
}
